const servicios = ['http://ollama:11434/api/tags', 'http://qdrant:6333/health', 'http://redis:6379', 'http://floowise:3000', 'http://openwebui:8080'];
const nombres = ['Ollama', 'Qdrant', 'Redis', 'Flowise', 'OpenWebUI'];
const resultados = [];

for (let i = 0; i < servicios.length; i++) {
  try {
    const res = await this.helpers.httpRequest({ method: 'GET', url: servicios[i], timeout: 5000 });
    resultados.push({ servicio: nombres[i], estado: 'saludable', codigo: 200 });
  } catch(e) {
    resultados.push({ servicio: nombres[i], estado: 'caído', error: e.message });
  }
}

const saludables = resultados.filter(r => r.estado === 'saludable').length;
return resultados.map(r => ({ json: { ...r, total: servicios.length, saludables, timestamp: new Date().toISOString() } }));
